import {DB} from './storage.js?v=11';import {requireAuth,bindShell,can,permissionsFor} from './auth.js?v=7';import {$,$$,fmtDate,esc,toast,download,uid} from './utils.js';import {groupBy,listHtml} from './reportes.js';import {downloadPdf} from './pdf-download.js';import {signature} from './signature.js?v=3';
const session=await requireAuth('administracion');if(!session)await new Promise(()=>{});bindShell();$('#welcome').textContent=`Bienvenido, ${session.nombre}. Esta es la situación actual de mantenimiento.`;$('#today').textContent=new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',year:'numeric'}).format(new Date());const configNav=document.querySelector('[data-section="config"]');if(!can(session,'configuracion'))configNav?.remove();
let current=[];const records=()=>DB.records();
const continuityLabel=record=>record.esContinuidad?`Continuidad de ${record.continuidadDeFolio||'otra bitácora'}`:record.continuaciones?.length?`Con seguimiento: ${record.continuaciones.map(item=>item.folio).join(', ')}`:'Sin continuidad vinculada';
const commitmentLabel=record=>record.estado!=='Concluido'&&record.continuidadFecha?`Compromiso: ${record.continuidadFecha}${record.continuidadHora?` · ${record.continuidadHora}`:''}`:'';
const continuityState=record=>record.continuidadEstado&&record.continuidadEstado!=='No requerida'?record.continuidadEstado:(record.terminado==='No'?'Pendiente':'—');
const statusHtml=record=>{const status=record.estado||'Pendiente';return`<span class="status ${status.replace(' ','-')}">${esc(status)}</span>${record.esContinuidad||record.continuaciones?.length?`<small class="continuity-status">${esc(continuityState(record))} · Continuidad</small>`:''}`};
$$('.nav-btn').forEach(b=>b.onclick=()=>{$$('.nav-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.section').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.section).classList.add('active');if(b.dataset.section==='records')renderTable();if(b.dataset.section==='staff')renderStaff();if(b.dataset.section==='reports')renderReports();if(b.dataset.section==='config')renderConfig()});
function renderDashboard(){const r=records(),year=new Date().getFullYear(),recordDate=x=>new Date(x.fechaServicio?`${x.fechaServicio}T12:00:00`:x.createdAt),completed=r.filter(x=>x.estado==='Concluido').length,pending=r.filter(x=>x.estado==='Pendiente'||x.estado==='En proceso').length;const ks=[['Bitácoras realizadas',r.length,'Total registrado'],['Pendientes',pending,'Requieren seguimiento'],['Concluidas',completed,'Servicios terminados']];$('#kpis').innerHTML=ks.map(x=>`<article class="card kpi"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></article>`).join('');const months=[...Array(12)].map((_,month)=>{const d=new Date(year,month,1);return{month,label:d.toLocaleDateString('es-MX',{month:'long'}),year}}),monthValues=months.map(m=>{const items=r.filter(x=>{const d=recordDate(x);return d.getFullYear()===m.year&&d.getMonth()===m.month});return{total:items.length,done:items.filter(x=>x.estado==='Concluido').length,pending:items.filter(x=>x.estado!=='Concluido').length}}),monthMax=Math.max(...monthValues.map(x=>x.total),1);$('#monthlyChart').innerHTML=months.map((m,i)=>`<div class="bar" title="${m.label}: ${monthValues[i].total} bitácoras" style="height:${Math.max(3,monthValues[i].total/monthMax*100)}%"><span>${m.label}<br><b>${monthValues[i].total}</b></span></div>`).join('');$('#monthlyTable').innerHTML=`<table><thead><tr><th>Mes ${year}</th><th>Total</th><th>Pendientes</th><th>Concluidas</th></tr></thead><tbody>${months.map((m,i)=>`<tr><td>${m.label}</td><td>${monthValues[i].total}</td><td>${monthValues[i].pending}</td><td>${monthValues[i].done}</td></tr>`).join('')}</tbody></table>`;const locations=groupBy(r,'predio'),maxLocation=Math.max(...Object.values(locations),1);$('#locationMetrics').innerHTML=Object.entries(locations).sort((a,b)=>b[1]-a[1]).map(([name,total])=>`<div class="location-row"><div><strong>${esc(name)}</strong><span>${total} bitácora${total===1?'':'s'}</span></div><div class="location-track"><i style="width:${total/maxLocation*100}%"></i></div></div>`).join('')||'<div class="empty">Todavía no hay ubicaciones registradas.</div>';}
const selects={filterProperty:()=>DB.properties(),filterResponsible:()=>[...new Set([...DB.settings().responsibles,...DB.users().filter(user=>user.rol==='encargado').map(user=>user.nombre)])]};Object.entries(selects).forEach(([id,get])=>get().forEach(x=>$('#'+id).add(new Option(x,x))));
const staffNames=[...new Set([...DB.settings().responsibles,...DB.users().filter(user=>user.rol==='encargado').map(user=>user.nombre)])].filter(name=>name!=='Contratista');staffNames.forEach(name=>$('#staffSelect').add(new Option(name,name)));
function renderStaff(){const name=$('#staffSelect').value,items=records().filter(record=>record.responsable===name||record.createdBy===name);$('#staffEmpty').classList.toggle('hidden',Boolean(name));$('#staffContent').classList.toggle('hidden',!name);if(!name)return;const completed=items.filter(record=>record.estado==='Concluido').length,pending=items.filter(record=>record.estado==='Pendiente').length,active=items.filter(record=>record.estado==='En proceso').length,progress=items.length?Math.round(completed/items.length*100):0;$('#staffKpis').innerHTML=[['Servicios asignados',items.length],['Concluidos',completed],['Pendientes',pending+active],['Avance general',`${progress}%`]].map(item=>`<article class="card kpi"><span>${item[0]}</span><strong>${item[1]}</strong><small>${name}</small></article>`).join('');$('#staffRows').innerHTML=items.map(record=>`<tr><td><strong>${esc(record.folio)}</strong>${record.esContinuidad?'<br><small>Continuidad</small>':''}</td><td>${fmtDate(record.fechaServicio||record.createdAt)}</td><td><strong>${esc(record.cliente)}</strong><br><small>${esc(record.predio)} · ${esc(record.espacio)}</small></td><td>${esc(record.tipo)}</td><td>${statusHtml(record)}</td><td>${record.estado==='Concluido'?'100%':record.estado==='En proceso'?'50%':'Pendiente'}</td><td>${record.photos?.length||0}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Este encargado todavía no tiene servicios registrados.</td></tr>';}
$('#staffSelect').onchange=renderStaff;
function filtered(){let q=$('#search').value.toLowerCase(),type=$('#filterType').value.toLowerCase();return records().filter(r=>(!q||Object.values(r).some(v=>typeof v==='string'&&v.toLowerCase().includes(q)))&&(!$('#filterDate').value||(r.fechaServicio||r.createdAt.slice(0,10))===$('#filterDate').value)&&(!$('#filterProperty').value||r.predio===$('#filterProperty').value)&&(!$('#filterSpace').value||r.espacio?.toLowerCase().includes($('#filterSpace').value.toLowerCase()))&&(!$('#filterResponsible').value||r.responsable===$('#filterResponsible').value||r.createdBy===$('#filterResponsible').value)&&(!$('#filterStatus').value||(r.estado||'Pendiente')===$('#filterStatus').value)&&(!type||r.tipo?.toLowerCase().includes(type)))}
function renderTable(){current=filtered();$('#empty').classList.toggle('hidden',current.length>0);$('#recordRows').innerHTML=current.map(r=>{const date=r.fechaServicio?`${r.fechaServicio}T12:00:00`:r.createdAt;return`<tr><td><strong>${esc(r.folio)}</strong>${r.esContinuidad?'<br><small>Bitácora de continuidad</small>':''}</td><td>${fmtDate(date)}</td><td><strong>${esc(r.cliente)}</strong><br><small>${esc(r.predio)} · ${esc(r.espacio)}</small></td><td>${esc(r.responsable)}${r.realizador?`<br><small>Realizó: ${esc(r.realizador)}</small>`:''}</td><td><span class="tag">${esc(r.tipo)}</span></td><td>${statusHtml(r)}</td><td>${esc(r.horaInicio)}–${esc(r.horaTermino||'—')}</td><td><strong>${esc(continuityState(r))}</strong><br><small>${esc(continuityLabel(r))}</small>${commitmentLabel(r)?`<br><small class="commitment-date">${esc(commitmentLabel(r))}</small>`:''}</td><td>${r.photos?.length||0}</td><td>${r.confirmacion?'Sí':'No'}</td><td class="actions"><button title="Ver" data-action="view" data-id="${r.id}">◉</button><button title="Editar" data-action="edit" data-id="${r.id}">✎</button><button title="Duplicar" data-action="copy" data-id="${r.id}">⧉</button><button title="Imprimir/PDF" data-action="print" data-id="${r.id}">▣</button>${can(session,'configuracion')?`<button title="Eliminar" data-action="delete" data-id="${r.id}">⌫</button>`:''}</td></tr>`}).join('')}
$$('.filters input,.filters select').forEach(x=>x.oninput=renderTable);$('#clearFilters').onclick=()=>{$$('.filters input,.filters select').forEach(x=>x.value='');renderTable()};
$('#recordRows').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const r=records().find(x=>x.id===b.dataset.id);if(b.dataset.action==='view')showDetail(r);if(b.dataset.action==='print'){showDetail(r);document.body.classList.add('printing-detail');setTimeout(()=>window.print(),100)}if(b.dataset.action==='edit'){const estado=prompt('Estado: Concluido, Pendiente o En proceso',r.estado);if(!['Concluido','Pendiente','En proceso'].includes(estado))return toast('Estado no válido','error');const descripcion=prompt('Descripción del servicio',r.descripcion);if(descripcion===null)return;let compromiso='';if(estado!=='Concluido'){compromiso=prompt('Fecha compromiso obligatoria (AAAA-MM-DD)',r.continuidadFecha||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(compromiso||''))return toast('Captura una fecha compromiso válida.','error')}r.estado=estado;r.terminado=estado==='Concluido'?'Sí':'No';r.continuidadEstado=estado==='Concluido'?(r.esContinuidad||r.continuaciones?.length?'Concluida':'No requerida'):'En proceso';if(compromiso)r.continuidadFecha=compromiso;r.descripcion=descripcion.trim()||r.descripcion;r.updatedAt=new Date().toISOString();r.history=[...(r.history||[]),{action:estado==='Concluido'?'Servicio finalizado desde Administración':`Seguimiento actualizado · compromiso ${compromiso}`,at:r.updatedAt,by:session.nombre}];try{await DB.saveRecord(r);if(r.esContinuidad&&r.continuidadDeId){const origin=records().find(item=>item.id===r.continuidadDeId);if(origin){origin.estado=estado==='Concluido'?'Concluido':'En proceso';origin.terminado=estado==='Concluido'?'Sí':'No';origin.continuidadEstado=estado==='Concluido'?'Concluida':'En proceso';if(compromiso)origin.continuidadFecha=compromiso;origin.updatedAt=r.updatedAt;origin.history=[...(origin.history||[]),{action:estado==='Concluido'?`Finalizada con ${r.folio}`:`Nueva fecha compromiso desde ${r.folio}: ${compromiso}`,at:r.updatedAt,by:session.nombre}];await DB.saveRecord(origin)}}DB.audit('Edición',r.folio);renderTable();renderDashboard();toast(estado==='Concluido'&&r.esContinuidad?'La continuidad y la bitácora original quedaron finalizadas.':'Cambios guardados y sincronizados.')}catch(error){console.error(error);toast('No se pudieron guardar los cambios en la nube.','error')}}if(b.dataset.action==='copy'){const n=structuredClone(r);n.id=uid();n.folio=DB.nextFolio();n.createdAt=new Date().toISOString();n.updatedAt=n.createdAt;n.history=[...(n.history||[]),{action:`Duplicado de ${r.folio}`,at:n.createdAt,by:session.nombre}];try{const saved=await DB.saveRecord(n);DB.audit('Duplicación',saved.folio);renderTable();renderDashboard();toast('Bitácora duplicada y sincronizada.')}catch(error){console.error(error);toast('No se pudo duplicar la bitácora.','error')}}if(b.dataset.action==='delete'&&can(session,'configuracion')&&confirm(`¿Eliminar definitivamente ${r.folio}?`)){try{await DB.removeRecord(r.id);DB.audit('Eliminación',r.folio);renderTable();renderDashboard();toast('Bitácora eliminada.')}catch(error){console.error(error);toast('No se pudo eliminar la bitácora.','error')}}};
function showDetail(r){const status=r.estado||'Pendiente',date=r.fechaServicio?`${r.fechaServicio}T12:00:00`:r.createdAt,photos=r.photos||[],clientSignature=r.clientSignature?`<img src="${r.clientSignature}" alt="Firma del cliente" style="max-width:100%;height:100px">`:'<p class="missing-media">Sin firma separada</p>',vpSignature=r.vpSignature?`<img src="${r.vpSignature}" alt="Firma de quien realizó el trabajo" style="max-width:100%;height:100px">`:'<p class="missing-media">Sin firma separada</p>';$('#detailBody').innerHTML=`<article class="print-sheet"><div class="detail-head"><div class="detail-brand"><img src="assets/logo/vallejo-properties.png" alt="Vallejo Properties"><img src="assets/logo/mantenimiento.jpg" alt="Mantenimiento"></div><div><small>FOLIO</small><h2>${esc(r.folio)}</h2><small>${fmtDate(date)}</small></div></div><div class="detail-grid">${[['Cliente',r.cliente],['Predio',r.predio],['Espacio',r.espacio],['Encargado',r.responsable],['Realizó el trabajo',r.realizador||'—'],['Tipo de mantenimiento',r.tipo],['Estado',status],['Estado de continuidad',continuityState(r)],['Horario',`${r.horaInicio||'—'}–${r.horaTermino||'—'}`]].map(x=>`<div class="detail-item"><small>${x[0]}</small><strong>${esc(x[1])}</strong></div>`).join('')}</div>${r.esContinuidad||r.continuaciones?.length?`<div class="continuity-detail"><h3>Relación de continuidad</h3><p>${esc(continuityLabel(r))}</p></div>`:''}<h3>Descripción del trabajo</h3><p>${esc(r.descripcion)}</p><h3>Observaciones</h3><p>${esc(r.observaciones||'Sin observaciones')}</p>${r.terminado==='No'&&r.continuidadFecha?`<h3>Próxima continuidad</h3><p>${fmtDate(`${r.continuidadFecha}T12:00:00`)} ${esc(r.continuidadHora)} · ${esc(r.continuidadMotivo)}</p>`:''}<h3>Evidencias (${photos.length})</h3><div class="evidence-strip">${photos.length?photos.map(x=>`<img src="${x}" alt="Evidencia del servicio">`).join(''):`<p class="missing-media">${r.recuperada?'Las evidencias están incluidas en el PDF original.':'Sin fotografías.'}</p>`}</div><div class="detail-grid signature-grid"><div class="signature-block"><h3>Firma del cliente</h3>${clientSignature}<p>${esc(r.clienteFirmaNombre||'')} ${r.clienteCargo?`· ${esc(r.clienteCargo)}`:''}</p></div><div class="signature-block"><h3>Firma de quien realizó el trabajo</h3>${vpSignature}<p>${esc(r.realizador||r.responsable)}</p></div><div class="history-block"><h3>Historial</h3>${(r.history||[]).map(h=>`<small>${fmtDate(h.at)} · ${esc(h.action)} · ${esc(h.by)}</small><br>`).join('')}</div></div></article>`;$('#detailDialog').showModal()}$('#printDetail').onclick=()=>{document.body.classList.add('printing-detail');setTimeout(()=>window.print(),80)};window.addEventListener('afterprint',()=>document.body.classList.remove('printing-detail'));
function exportRows(sep=','){const cols=['folio','fechaServicio','cliente','predio','espacio','responsable','realizador','tipo','estado','horaInicio','horaTermino','esContinuidad','continuidadDeFolio','continuidadEstado','continuidadFecha'];return[cols.join(sep),...filtered().map(r=>cols.map(k=>`"${String(r[k]||'').replaceAll('"','""')}"`).join(sep))].join('\n')}$('#csvBtn').onclick=()=>download('bitacoras-vp.csv','\ufeff'+exportRows(),'text/csv');$('#excelBtn').onclick=()=>download('bitacoras-vp.xls','\ufeff'+exportRows('\t'),'application/vnd.ms-excel');
function reportRecordDate(record){return new Date(record.fechaServicio?`${record.fechaServicio}T12:00:00`:record.createdAt)}
function selectedReportRecords(){const period=$('#reportPeriod').value,value=$('#reportReference').value,staff=$('#reportStaff').value,property=$('#reportProperty').value;if(!value)return[];let items;if(period==='week'){const chosen=new Date(`${value}T12:00:00`),start=new Date(chosen),day=(start.getDay()+6)%7;start.setDate(start.getDate()-day);start.setHours(0,0,0,0);const end=new Date(start);end.setDate(end.getDate()+7);items=records().filter(record=>{const d=reportRecordDate(record);return d>=start&&d<end})}else if(period==='month'){const [year,month]=value.split('-').map(Number);items=records().filter(record=>{const d=reportRecordDate(record);return d.getFullYear()===year&&d.getMonth()===month-1})}else{const year=Number(value);items=records().filter(record=>reportRecordDate(record).getFullYear()===year)}return items.filter(record=>(!staff||record.responsable===staff||record.createdBy===staff)&&(!property||record.predio===property))}
function renderReportTable(){const items=selectedReportRecords();$('#reportTotal').textContent=items.length;$('#reportEmpty').classList.toggle('hidden',items.length>0);$('#reportRows').innerHTML=items.map(record=>`<tr><td><strong>${esc(record.folio)}</strong>${record.esContinuidad?'<br><small>Continuidad</small>':''}</td><td>${fmtDate(record.fechaServicio?`${record.fechaServicio}T12:00:00`:record.createdAt)}</td><td>${esc(record.cliente)}</td><td>${esc(record.predio)}<br><small>${esc(record.espacio)}</small></td><td>${esc(record.responsable)}${record.realizador?`<br><small>Realizó: ${esc(record.realizador)}</small>`:''}</td><td>${esc(record.tipo)}</td><td>${statusHtml(record)}</td></tr>`).join('')}
function configureReportPeriod(){const period=$('#reportPeriod').value,input=$('#reportReference'),now=new Date();if(period==='week'){input.type='date';input.value=now.toISOString().slice(0,10);$('#reportReferenceLabel').textContent='Semana que contiene la fecha'}else if(period==='month'){input.type='month';input.value=now.toISOString().slice(0,7);$('#reportReferenceLabel').textContent='Mes'}else{input.type='number';input.min='2000';input.max='2100';input.value=now.getFullYear();$('#reportReferenceLabel').textContent='Año'}renderReports()}
function renderReports(){const r=selectedReportRecords();renderReportTable();$('#byProperty').innerHTML=listHtml(groupBy(r,'predio'));$('#byResponsible').innerHTML=listHtml(groupBy(r,'responsable'));$('#byType').innerHTML=listHtml(groupBy(r,'tipo'));$('#byPriority').innerHTML=listHtml(groupBy(r,'estado'))}
staffNames.forEach(name=>$('#reportStaff').add(new Option(name,name)));DB.properties().forEach(property=>$('#reportProperty').add(new Option(property,property)));$('#reportPeriod').onchange=configureReportPeriod;$('#reportReference').oninput=renderReports;$('#reportStaff').onchange=renderReports;$('#reportProperty').onchange=renderReports;configureReportPeriod();
function reportPeriodTitle(){const period=$('#reportPeriod').value,value=$('#reportReference').value;if(period==='week'){const date=new Date(`${value}T12:00:00`),start=new Date(date),day=(start.getDay()+6)%7;start.setDate(start.getDate()-day);const end=new Date(start);end.setDate(end.getDate()+6);return`Semana del ${start.toLocaleDateString('es-MX')} al ${end.toLocaleDateString('es-MX')}`}if(period==='month'){const [year,month]=value.split('-').map(Number);return new Date(year,month-1,1).toLocaleDateString('es-MX',{month:'long',year:'numeric'})}return`Año ${value}`}
function buildReportPdf(){const items=selectedReportRecords(),done=items.filter(record=>record.estado==='Concluido').length,pending=items.length-done;$('#reportPdfBody').innerHTML=`<header class="pdf-head"><div><span class="pdf-brand-pair"><img src="assets/logo/vallejo-properties.png" alt="Vallejo Properties"><img src="assets/logo/mantenimiento.jpg" alt="Mantenimiento"></span></div><div><small>REPORTE DE BITÁCORAS</small><strong>${reportPeriodTitle()}</strong></div></header><section class="pdf-title"><h1>Reporte de mantenimiento</h1><p>Generado el ${new Date().toLocaleDateString('es-MX',{dateStyle:'long'})}</p></section><section class="pdf-stats"><div><small>Total</small><strong>${items.length}</strong></div><div><small>Pendientes</small><strong>${pending}</strong></div><div><small>Concluidas</small><strong>${done}</strong></div></section><table class="pdf-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Cliente / ubicación</th><th>Encargado / realizó</th><th>Tipo de mantenimiento</th><th>Estado</th></tr></thead><tbody>${items.map(record=>`<tr><td>${esc(record.folio)}${record.esContinuidad?'<br><small>Continuidad</small>':''}</td><td>${fmtDate(record.fechaServicio?`${record.fechaServicio}T12:00:00`:record.createdAt)}</td><td><strong>${esc(record.cliente)}</strong><br>${esc(record.predio)} · ${esc(record.espacio)}</td><td>${esc(record.responsable)}${record.realizador?`<br><small>Realizó: ${esc(record.realizador)}</small>`:''}</td><td>${esc(record.tipo)}<br><small>${esc(continuityLabel(record))}</small></td><td>${esc(record.estado||'Pendiente')}<br><small>${esc(continuityState(record))}</small></td></tr>`).join('')||'<tr><td colspan="6">Sin bitácoras en este periodo</td></tr>'}</tbody></table><footer class="pdf-footer">Bitácora Digital de Mantenimiento · Vallejo Properties</footer>`;$('#reportPdfDialog').showModal()}
$('#previewReportPdf').onclick=buildReportPdf;$('#saveReportPdf').textContent='Descargar PDF';$('#saveReportPdf').onclick=async()=>{const items=selectedReportRecords(),button=$('#saveReportPdf'),period=reportPeriodTitle();button.disabled=true;button.textContent='Preparando PDF…';try{await downloadPdf({filename:`reporte-mantenimiento-${new Date().toISOString().slice(0,10)}.pdf`,title:'Reporte de mantenimiento',lines:[{label:'Periodo',value:period},{label:'Encargado',value:$('#reportStaff').selectedOptions[0]?.textContent||'Todos'},{label:'Predio',value:$('#reportProperty').selectedOptions[0]?.textContent||'Todos'},{label:'Total de bitácoras',value:items.length},...items.flatMap(record=>['',`${record.folio} · ${fmtDate(record.fechaServicio?`${record.fechaServicio}T12:00:00`:record.createdAt)}`,`Cliente: ${record.cliente||'—'} · Ubicación: ${record.predio||'—'} / ${record.espacio||'—'}`,`Encargado: ${record.responsable||'—'} · Realizó: ${record.realizador||'—'}`,`Tipo de mantenimiento: ${record.tipo||'—'} · Estado: ${record.estado||'Pendiente'}`,`Continuidad: ${continuityState(record)} · ${continuityLabel(record)}`])]});toast('Reporte PDF descargado correctamente.')}catch(error){console.error(error);toast('No fue posible generar el reporte PDF','error')}finally{button.disabled=false;button.textContent='Descargar PDF'}};
function renderConfig(){const props=DB.properties(),users=DB.users(),s=DB.settings();$('#propertyList').innerHTML=props.map((p,i)=>`<div class="list-row"><span>${esc(p)}</span><span><button class="btn" data-edit-property="${i}">Editar</button> <button class="btn danger" data-property="${i}">Eliminar</button></span></div>`).join('');$('#userList').innerHTML=users.map(u=>`<div class="list-row"><span><strong>${esc(u.nombre)}</strong><br><small>${esc(u.usuario)} · ${u.rol}</small></span><button class="btn" data-user="${u.id}">${u.activo?'Desactivar':'Activar'}</button></div>`).join('');$('#nextFolio').value=s.nextFolio;$('#catalogSummary').innerHTML=`<button class="btn" data-add-catalog="types">+ Tipo</button> <button class="btn" data-add-catalog="responsibles">+ Responsable</button><h3>Tipos de servicio</h3>${s.types.map((x,i)=>`<div class="list-row"><span>${esc(x)}</span><button class="btn danger" data-catalog="types" data-index="${i}">×</button></div>`).join('')}<h3>Responsables</h3>${s.responsibles.map((x,i)=>`<div class="list-row"><span>${esc(x)}</span><button class="btn danger" data-catalog="responsibles" data-index="${i}">×</button></div>`).join('')}`}
