$('#editRecordForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form)),record=records().find(item=>item.id===data.id);if(!record)return;['cliente','predio','espacio','responsable','realizador','tipo','estado','continuidadFecha','descripcion','observaciones','clienteFirmaNombre','clienteCargo'].forEach(name=>record[name]=data[name]||'');record.continuidadNoDefinida=form.elements.continuidadNoDefinida.checked;record.terminado=record.estado==='Concluido'?'Sí':'No';record.clientSignature=editClientSig.isEmpty()?'':editClientSig.data();record.vpSignature=editVpSig.isEmpty()?'':editVpSig.data();record.firmasPendientes=!record.clientSignature||!record.vpSignature;record.updatedAt=new Date().toISOString();record.history=[...(record.history||[]),{action:'Contenido y firmas editados desde Administración',at:record.updatedAt,by:session.nombre}];try{await DB.saveRecord(record);$('#editRecordDialog').close();renderTable();renderDashboard();toast('Contenido y firmas actualizados.')}catch(error){console.error(error);toast('No se pudieron guardar los cambios.','error')}};

