function buildBatchReport(items,name,role,sig){$('#batchReportBody').innerHTML=`<header class="pdf-head"><div class="pdf-brand-pair"><img src="assets/logo/vallejo-properties.png"><img src="assets/logo/mantenimiento.jpg"></div><div><small>REPORTE CONSOLIDADO</small><strong>${esc($('#batchMonth').value||'Bitácoras seleccionadas')}</strong></div></header><section class="pdf-title"><h1>Conformidad de bitácoras</h1><p>${items.length} servicios seleccionados</p></section><table class="pdf-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Cliente / predio</th><th>Servicio</th><th>Estado</th></tr></thead><tbody>${items.map(r=>`<tr><td>${r.esVip?'★ VIP<br>':''}${esc(r.folio)}</td><td>${fmtDate(r.fechaServicio?`${r.fechaServicio}T12:00:00`:r.createdAt)}</td><td>${esc(r.cliente)}<br>${esc(r.predio)} · ${esc(r.espacio)}</td><td>${esc(r.tipo)}<br><small>${esc(r.descripcion)}</small></td><td>${esc(r.estado)}</td></tr>`).join('')}</tbody></table><section class="batch-report-signature"><p>Manifiesto mi conformidad con los servicios relacionados en este reporte.</p><img src="${sig}"><strong>${esc(name)}</strong><span>${esc(role)}</span></section><footer class="pdf-footer">Bitácora Digital de Mantenimiento · Vallejo Properties</footer>`}
