$('#saveBatchSignatures').onclick=async()=>{const ids=[...$('#batchRecordList').querySelectorAll('input:checked')].map(input=>input.value),items=records().filter(record=>ids.includes(record.id)),name=$('#batchSignerName').value.trim(),role=$('#batchSignerRole').value.trim();if(!items.length)return toast('Selecciona al menos una bitácora.','error');if(!name)return toast('Captura el nombre de quien firma.','error');if(batchSig.isEmpty())return toast('Recopila la firma de conformidad.','error');const signatureData=batchSig.data(),createdAt=new Date().toISOString(),snapshot=items.map(record=>({...record}));try{for(const record of items){record.clientSignature=signatureData;record.clienteFirmaNombre=name;record.clienteCargo=role;record.confirmacion=true;record.firmasPendientes=!record.vpSignature;record.updatedAt=createdAt;record.history=[...(record.history||[]),{action:`Firma recopilada en reporte consolidado (${items.length} bitácoras)`,at:createdAt,by:session.nombre}];await DB.saveRecord(record)}const archived=await DB.saveSignatureReport({id:uid(),title:`Conformidad · ${$('#batchMonth').value||'Bitácoras seleccionadas'}`,period:$('#batchMonth').value,createdAt,createdBy:session.nombre,signerName:name,signerRole:role,signature:signatureData,recordIds:ids,items:snapshot});buildBatchReport(snapshot,name,role,signatureData);$('#batchSignatureDialog').close();$('#batchReportDialog').showModal();renderTable();toast(archived._pendingSync?'Reporte guardado en este dispositivo; se sincronizará al recuperar internet.':'Firma y reporte guardados y sincronizados.')}catch(error){console.error(error);toast('No fue posible guardar el reporte.','error')}};
