renderTable();

// Galería completa de reportes consolidados con vista previa y descarga individual.
renderBatchReportArchive=()=>{const reports=DB.signatureReports();$('#batchReportCount').textContent=`${reports.length} ${reports.length===1?'reporte':'reportes'}`;$('#batchReportArchiveList').innerHTML=reports.map(report=>{const items=Array.isArray(report.items)?report.items:[];return`<article class="archived-report report-preview-card"><div class="report-preview-sheet"><span>REPORTE DE CONFORMIDAD</span><strong>${esc(report.period||'Periodo personalizado')}</strong><b>${items.length} ${items.length===1?'bitácora':'bitácoras'}</b><ul>${items.slice(0,3).map(item=>`<li>${item.esVip?'★ ':''}${esc(item.folio||'Sin folio')} · ${esc(item.predio||'Sin predio')}</li>`).join('')}${items.length>3?`<li>+ ${items.length-3} más</li>`:''}</ul><small>Firma: ${esc(report.signerName||'Pendiente')}</small></div><div class="archived-report-info"><strong>${esc(report.title||'Reporte consolidado')}</strong><small>${fmtDate(report.createdAt)} · ${items.length} bitácoras · ${esc(report.signerName||'Sin nombre')}</small><div class="archived-report-actions"><button class="btn" type="button" data-view-batch-report="${report.id}">Vista previa</button><button class="btn primary" type="button" data-download-batch-report="${report.id}">Guardar PDF</button></div></div></article>`}).join('')||'<p class="empty">Todavía no se han generado reportes de firmas.</p>'};
async function downloadArchivedReport(report,button){const items=Array.isArray(report.items)?report.items:[];button.disabled=true;const prior=button.textContent;button.textContent='Preparando…';try{await downloadPdf({filename:`conformidad-${report.period||new Date(report.createdAt).toISOString().slice(0,10)}.pdf`,title:report.title||'Reporte consolidado de conformidad',lines:[{label:'Periodo',value:report.period||'Personalizado'},{label:'Firmó',value:report.signerName||'—'},{label:'Cargo',value:report.signerRole||'—'},{label:'Total de bitácoras',value:items.length},...items.flatMap(item=>['',`${item.esVip?'★ VIP · ':''}${item.folio||'Sin folio'} · ${fmtDate(item.fechaServicio?`${item.fechaServicio}T12:00:00`:item.createdAt)}`,`${item.cliente||'Sin cliente'} · ${item.predio||'Sin predio'} · ${item.tipo||'Sin servicio'} · ${item.estado||'Pendiente'}`])],images:report.signature?[{src:report.signature,label:`Firma de ${report.signerName||'conformidad'}`}]:[]});toast('Reporte guardado en PDF en este dispositivo.')}catch(error){console.error(error);toast('No fue posible guardar este reporte.','error')}finally{button.disabled=false;button.textContent=prior}}
$('#batchReportArchiveList').onclick=event=>{const view=event.target.closest('[data-view-batch-report]'),save=event.target.closest('[data-download-batch-report]'),id=view?.dataset.viewBatchReport||save?.dataset.downloadBatchReport;if(!id)return;const report=DB.signatureReports().find(item=>item.id===id);if(!report)return toast('No se encontró el reporte.','error');if(save)return downloadArchivedReport(report,save);$('#batchMonth').value=report.period||'';buildBatchReport(report.items||[],report.signerName,report.signerRole,report.signature);$('#batchSignatureDialog').close();$('#batchReportDialog').showModal()};

// Recuperación de bitácoras que solo fueron descargadas como PDF.
recordsActions?.insertAdjacentHTML('afterbegin','<button class="btn" id="openRecoveredPdfImport">⬆ Cargar bitácoras descargadas</button> ');
document.body.insertAdjacentHTML('beforeend',`<dialog id="recoveredPdfDialog"><div class="modal-head"><strong>Cargar bitácoras descargadas</strong><button class="btn" type="button" id="closeRecoveredPdfImport">Cerrar</button></div><div class="modal-body recovered-pdf-import"><p>Selecciona los PDF que no fueron guardados en el sistema. Cada archivo recibirá un folio nuevo y conservará la referencia de su folio y fecha originales.</p><label class="recovered-pdf-picker"><input id="recoveredPdfFiles" type="file" accept="application/pdf,.pdf" multiple><strong>Seleccionar bitácoras PDF</strong><small>Puedes cargar varios archivos al mismo tiempo.</small></label><div id="recoveredPdfList" class="recovered-pdf-list"></div><div class="dialog-actions"><button class="btn primary" id="saveRecoveredPdfs" type="button" disabled>Guardar en Administración</button></div></div></dialog>`);
const recoveredFiles=[];
const readPdf=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)});
const originalFolioFromName=name=>name.match(/VP[-_ ]?(\d{1,6})/i)?.[1]?.padStart(6,'0')||'';
function renderRecoveredFiles(){
  $('#recoveredPdfList').innerHTML=recoveredFiles.map((item,index)=>`<article class="recovered-pdf-card" data-recovered-index="${index}"><div class="recovered-pdf-icon">PDF</div><div class="recovered-pdf-fields"><strong>${esc(item.file.name)}</strong><div class="grid"><div class="field col-4"><label>Folio original *</label><input data-field="originalFolio" value="${esc(item.originalFolio?`VP-${item.originalFolio}`:'')}"></div><div class="field col-4"><label>Fecha original *</label><input data-field="originalDate" type="date" value="${esc(item.originalDate||'')}"></div><div class="field col-4"><label>Estado</label><select data-field="estado"><option>Concluido</option><option>Pendiente</option><option>En proceso</option></select></div><div class="field col-4"><label>Cliente</label><input data-field="cliente" value="${esc(item.cliente||'')}"></div><div class="field col-4"><label>Predio</label><input data-field="predio" value="${esc(item.predio||'')}"></div><div class="field col-4"><label>Encargado</label><input data-field="responsable" value="${esc(item.responsable||'Cristina')}"></div><div class="field col-12"><label>Nota de recuperación</label><input data-field="nota" value="${esc(item.nota||'')}"></div></div></div><button class="btn" type="button" data-remove-recovered="${index}">Quitar</button></article>`).join('');
  $('#saveRecoveredPdfs').disabled=!recoveredFiles.length;
}
$('#openRecoveredPdfImport').onclick=()=>{$('#recoveredPdfFiles').value='';recoveredFiles.splice(0);renderRecoveredFiles();$('#recoveredPdfDialog').showModal()};
$('#closeRecoveredPdfImport').onclick=()=>$('#recoveredPdfDialog').close();
$('#recoveredPdfFiles').onchange=async event=>{for(const file of event.target.files){if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))continue;const number=originalFolioFromName(file.name);recoveredFiles.push({file,data:await readPdf(file),originalFolio:number,originalDate:'',estado:'Concluido',cliente:'',predio:'',responsable:'Cristina',nota:number?`Bitácora recuperada del folio original VP-${number}.`:'Bitácora recuperada desde un PDF descargado.'})}renderRecoveredFiles()};
$('#recoveredPdfList').onclick=event=>{const remove=event.target.closest('[data-remove-recovered]');if(!remove)return;recoveredFiles.splice(Number(remove.dataset.removeRecovered),1);renderRecoveredFiles()};
$('#recoveredPdfList').oninput=event=>{const card=event.target.closest('[data-recovered-index]'),field=event.target.dataset.field;if(!card||!field)return;recoveredFiles[Number(card.dataset.recoveredIndex)][field]=event.target.value};
$('#recoveredPdfList').onchange=$('#recoveredPdfList').oninput;
$('#saveRecoveredPdfs').onclick=async()=>{const button=$('#saveRecoveredPdfs');for(const item of recoveredFiles){if(!item.originalFolio||!item.originalDate)return toast('Completa el folio y la fecha originales de cada PDF.','error');const normalized=item.originalFolio.toUpperCase().startsWith('VP-')?item.originalFolio.toUpperCase():`VP-${item.originalFolio.replace(/\D/g,'').padStart(6,'0')}`;if(records().some(record=>record.recuperada&&record.archivoOriginalNombre===item.file.name&&record.folioOriginal===normalized))return toast(`El archivo ${item.file.name} ya fue recuperado anteriormente.`,'error')}button.disabled=true;button.textContent='Guardando…';let saved=0;try{for(const item of recoveredFiles){const normalized=item.originalFolio.toUpperCase().startsWith('VP-')?item.originalFolio.toUpperCase():`VP-${item.originalFolio.replace(/\D/g,'').padStart(6,'0')}`,createdAt=new Date().toISOString(),record={id:uid(),folio:DB.nextFolio(),createdAt,updatedAt:createdAt,createdBy:session.nombre,fechaServicio:item.originalDate,cliente:item.cliente||'Sin cliente indicado',predio:item.predio||'Sin predio indicado',espacio:'Documento recuperado',responsable:item.responsable||session.nombre,realizador:'Según PDF original',tipo:'Bitácora recuperada desde PDF',estado:item.estado,terminado:item.estado==='Concluido'?'Sí':'No',descripcion:`Documento recuperado correspondiente al folio ${normalized}, con fecha original ${item.originalDate}.`,observaciones:item.nota||`Bitácora recuperada del folio original ${normalized}.`,registroTipo:'Trabajo',esVip:false,recuperada:true,folioOriginal:normalized,fechaOriginal:item.originalDate,archivoOriginalNombre:item.file.name,archivoOriginalPdf:item.data,photos:[],clientSignature:'',vpSignature:'',firmasPendientes:false,continuidadEstado:item.estado==='Concluido'?'No requerida':'Pendiente',history:[{action:`PDF recuperado del folio original ${normalized}`,at:createdAt,by:session.nombre}]};await DB.saveRecord(record);saved++}$('#recoveredPdfDialog').close();renderTable();renderDashboard();toast(`${saved} ${saved===1?'bitácora recuperada':'bitácoras recuperadas'} y sincronizadas.`)}catch(error){console.error(error);toast('No fue posible terminar la recuperación de los PDF.','error')}finally{button.disabled=false;button.textContent='Guardar en Administración'}};
const originalPdfData=record=>Promise.resolve(record.archivoOriginalPdf||DB.sourcePdf(record.id));
const pdfObjectUrl=data=>{const [meta,encoded]=data.split(','),bytes=atob(encoded),buffer=new Uint8Array(bytes.length);for(let index=0;index<bytes.length;index++)buffer[index]=bytes.charCodeAt(index);return URL.createObjectURL(new Blob([buffer],{type:meta.match(/data:([^;]+)/)?.[1]||'application/pdf'}))};
let activeRecoveredPreviewUrl='';
function clearRecoveredPreview(){if(activeRecoveredPreviewUrl){URL.revokeObjectURL(activeRecoveredPreviewUrl);activeRecoveredPreviewUrl=''}}
async function openRecoveredPdf(record,{download=false}={}){const data=await originalPdfData(record);if(!data)return toast('El PDF original no está disponible en este dispositivo.','error');const objectUrl=pdfObjectUrl(data),name=record.archivoOriginalNombre||`${record.folioOriginal||record.folio}.pdf`;if(download){const link=document.createElement('a');link.href=objectUrl;link.download=name;link.click()}else window.open(objectUrl,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(objectUrl),60000)}
const showDetailBeforeRecoveredPdf=showDetail;
showDetail=record=>{clearRecoveredPreview();showDetailBeforeRecoveredPdf(record);$('#printDetail').textContent=record.recuperada?'Abrir PDF original':'Imprimir / PDF';$('#printDetail').onclick=record.recuperada?()=>openRecoveredPdf(record):()=>{document.body.classList.add('printing-detail');setTimeout(()=>window.print(),80)};if(!record.recuperada)return;const notice=`<section class="recovered-pdf-notice"><strong>Bitácora recuperada</strong><span>Este registro recibió el folio ${esc(record.folio)} y corresponde al folio original ${esc(record.folioOriginal)} del ${fmtDate(`${record.fechaOriginal}T12:00:00`)}. Sus fotografías y firmas están dentro del documento original.</span><span class="recovered-pdf-buttons" data-recovered-pdf-action>Preparando vista previa…</span></section><section class="recovered-pdf-preview" data-recovered-pdf-preview><strong>Vista previa del reporte original</strong><div class="recovered-pdf-loading">Cargando PDF…</div></section>`;$('#detailBody .print-sheet').insertAdjacentHTML('afterbegin',notice);originalPdfData(record).then(data=>{const target=$('[data-recovered-pdf-action]'),preview=$('[data-recovered-pdf-preview]');if(!target||!preview)return;if(!data){target.innerHTML='<span>PDF original no disponible en este dispositivo.</span>';preview.innerHTML='<p class="missing-media">No fue posible cargar la vista previa.</p>';return}activeRecoveredPreviewUrl=pdfObjectUrl(data);target.innerHTML='<button class="btn primary" type="button" data-open-original-pdf>Abrir PDF completo</button><button class="btn" type="button" data-save-original-pdf>Guardar PDF</button>';preview.innerHTML=`<strong>Vista previa del reporte original</strong><iframe src="${activeRecoveredPreviewUrl}#toolbar=0&navpanes=0" title="Vista previa de ${esc(record.folioOriginal||record.folio)}"></iframe><small>Si tu teléfono no muestra la vista previa, usa “Abrir PDF completo”.</small>`;target.querySelector('[data-open-original-pdf]')?.addEventListener('click',()=>openRecoveredPdf(record));target.querySelector('[data-save-original-pdf]')?.addEventListener('click',()=>openRecoveredPdf(record,{download:true}))})};
$('#detailDialog').addEventListener('close',clearRecoveredPreview);
$('#recordRows').addEventListener('click',event=>{const button=event.target.closest('[data-action="print"]');if(!button)return;const record=records().find(item=>item.id===button.dataset.id);if(!record?.recuperada)return;event.preventDefault();event.stopImmediatePropagation();openRecoveredPdf(record)},true);
const renderTableBeforeRecovered=renderTable;
renderTable=()=>{renderTableBeforeRecovered();[...$('#recordRows').rows].forEach((row,index)=>{const record=current[index],cell=row.cells[0];if(!record?.recuperada||!cell)return;if(!cell.querySelector('.recovered-badge'))cell.insertAdjacentHTML('beforeend',`<br><span class="recovered-badge">PDF recuperado · original ${esc(record.folioOriginal)}</span>`);row.cells[8].innerHTML='<span class="recovered-table-note">En PDF</span>';row.cells[9].innerHTML='<span class="recovered-table-note">En PDF</span>';const view=row.querySelector('[data-action="view"]'),print=row.querySelector('[data-action="print"]');if(view)view.title='Ver información y PDF original';if(print){print.title='Abrir PDF original';print.textContent='PDF'}})};
renderTable();
